// Parse Groq API response
const groqResponse = $input.first().json;

try {
  // Extract content from Groq response
  const aiContent = groqResponse.choices[0].message.content;

  // Try to parse as JSON
  let parsed;
  if (typeof aiContent === 'string') {
    parsed = JSON.parse(aiContent);
  } else {
    parsed = aiContent;
  }

  return [{
    json: {
      alertId: $json.alertId,
      dstDomain: $json.dstDomain,
      severity: parsed.severity || "Unknown",
      reason: parsed.reason || "No reason provided",
      timestamp: new Date().toISOString()
    }
  }];
} catch (error) {
  // Fallback for parsing errors
  return [{
    json: {
      alertId: $json.alertId,
      dstDomain: $json.dstDomain,
      severity: "Error",
      reason: "Failed to parse AI response: " + error.message,
      timestamp: new Date().toISOString()
    }
  }];
}

// Format for Discord embed
const data = $input.first().json;

// Color mapping based on severity
const colorMap = {
  "Critical": 16711680,  // Red
  "High": 16753920,      // Orange
  "Medium": 16776960,    // Yellow
  "Low": 65280,          // Green
  "Error": 8421504,      // Gray
  "Unknown": 8421504     // Gray
};

const severity = data.severity || "Unknown";
const color = colorMap[severity] || 16711680;

return [{
  json: {
    embeds: [{
      title: "SentinelFlow Alert",
      color: color,
      fields: [
        {
          name: "Alert ID",
          value: data.alertId || "No ID",
          inline: true
        },
        {
          name: "Domain",
          value: data.dstDomain || "Unknown",
          inline: true
        },
        {
          name: "Severity",
          value: severity,
          inline: true
        },
        {
          name: "Reason",
          value: data.reason || "No analysis available",
          inline: false
        }
      ],
      timestamp: new Date().toISOString(),
      footer: {
        text: "SentinelFlow Security Automation"
      }
    }]
  }
}];
